using namespace std;
using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;

    // Two heaps for median tracking
    priority_queue<int64> left;  // max-heap
    priority_queue<int64, vector<int64>, greater<int64>> right; // min-heap

    int64 sum_left = 0, sum_right = 0;
    int64 constant = 0; // sum of b values

    for (int i = 0; i < Q; i++) {
        int t;
        cin >> t;
        if (t == 1) {
            int64 a, b;
            cin >> a >> b;
            constant += b;

            // Insert into heaps
            if (left.empty() || a <= left.top()) {
                left.push(a);
                sum_left += a;
            } else {
                right.push(a);
                sum_right += a;
            }

            // Balance so left size = right size or left size = right size + 1
            if (left.size() > right.size() + 1) {
                int64 val = left.top();
                left.pop();
                sum_left -= val;
                right.push(val);
                sum_right += val;
            } else if (right.size() > left.size()) {
                int64 val = right.top();
                right.pop();
                sum_right -= val;
                left.push(val);
                sum_left += val;
            }

        } else {
            int64 median = left.top();
            int64 left_cnt = left.size();
            int64 right_cnt = right.size();
            int64 min_val = (median * left_cnt - sum_left) + (sum_right - median * right_cnt) + constant;
            cout << median << " " << min_val << "\n";
        }
    }

    return 0;
}

