                lo.push(a);
                sum_lo += a;
            } else {
                hi.push(a);
                sum_hi += a;
            }

            // Rebalance: lo should have size >= hi and lo.size() - hi.size() <= 1
            while(lo.size() > hi.size() + 1){
                long long val = lo.top(); lo.pop();
                sum_lo -= val;
                hi.push(val);
                sum_hi += val;
