#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;

    priority_queue<long long> L; // max-heap
    priority_queue<long long, vector<long long>, greater<long long>> R; // min-heap

    long long addL = 0, addR = 0; // lazy offsets
    long long minValue = 0;

    auto topL = [&]() -> long long {
        return L.top() + addL;
    };
    auto topR = [&]() -> long long {
        return R.top() + addR;
    };
    auto pushL = [&](long long x) {
        L.push(x - addL);
    };
    auto pushR = [&](long long x) {
        R.push(x - addR);
    };

    for (int qi = 0; qi < Q; ++qi) {
        int t;
        cin >> t;
        if (t == 1) {
            long long a, b;
            cin >> a >> b;
            minValue += b;

            if (L.empty()) {
                pushL(a);
                pushR(a);
            } else {
                long long l = topL();
                long long r = topR();

                if (a < l) {
                    minValue += l - a;
                    pushL(a);
                    pushL(a);
                    pushR(l);
                    L.pop();
                } else if (a > r) {
                    minValue += a - r;
                    pushR(a);
                    pushR(a);
                    pushL(r);
                    R.pop();
                } else {
                    pushL(a);
                    pushR(a);
                }
            }
        } else {
            cout << topL() << ' ' << minValue << '\n';
        }
    }

    return 0;
}

