public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int Q = Integer.parseInt(br.readLine());

        // Two heaps to keep track of the median
        PriorityQueue<Long> maxHeap = new PriorityQueue<>(Collections.reverseOrder()); // left half
        PriorityQueue<Long> minHeap = new PriorityQueue<>(); // right half

        long sumLeft = 0, sumRight = 0;
        long shift = 0; // constant term from b

        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < Q; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int type = Integer.parseInt(st.nextToken());

            if (type == 1) {
                long a = Long.parseLong(st.nextToken());
                long b = Long.parseLong(st.nextToken());
                shift += b;

                // Insert a into the heaps
                if (maxHeap.isEmpty() || a <= maxHeap.peek()) {
                    maxHeap.add(a);
                    sumLeft += a;
                } else {
                    minHeap.add(a);
                    sumRight += a;
                }

                // Balance heaps: maxHeap size should be >= minHeap size
                if (maxHeap.size() > minHeap.size() + 1) {
                    long moved = maxHeap.poll();
                    sumLeft -= moved;
                    minHeap.add(moved);
                    sumRight += moved;
                } else if (minHeap.size() > maxHeap.size()) {
                    long moved = minHeap.poll();
                    sumRight -= moved;
                    maxHeap.add(moved);
                    sumLeft += moved;
                }
            } else {
                // type 2: evaluation
                long median = maxHeap.peek();
                long leftCount = maxHeap.size();
                long rightCount = minHeap.size();

                long minValue = (median * leftCount - sumLeft) + (sumRight - median * rightCount) + shift;
                sb.append(median).append(" ").append(minValue).append("\n");
            }
        }
        System.out.print(sb);
    }
}

