        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int Q = Integer.parseInt(br.readLine().trim());

        // max-heap for lower half
        PriorityQueue<Long> lower = new PriorityQueue<>(Collections.reverseOrder());
        // min-heap for upper half
        PriorityQueue<Long> upper = new PriorityQueue<>();

        long lowerSum = 0, upperSum = 0, totalB = 0;

        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < Q; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int type = Integer.parseInt(st.nextToken());
            if (type == 1) {
                long a = Long.parseLong(st.nextToken());
                long b = Long.parseLong(st.nextToken());
                totalB += b;
                // Insert a
                if (lower.isEmpty() || a <= lower.peek()) {
                    lower.add(a);
                    lowerSum += a;
                } else {
                    upper.add(a);
                    upperSum += a;
                }
                // Balance: lower.size() should be upper.size() or upper.size()+1
                while (lower.size() < upper.size()) {
                    long val = upper.poll();
                    upperSum -= val;
                    lower.add(val);
                    lowerSum += val;
                }
                while (lower.size() > upper.size() + 1) {
                    long val = lower.poll();
                    lowerSum -= val;
                    upper.add(val);
                    upperSum += val;
                }
            } else {
                long median = lower.peek();
                long minVal = median * (lower.size() - upper.size()) + upperSum - lowerSum + totalB;
                sb.append(median).append(' ').append(minVal).append('\n');
            }
        }
        System.out.print(sb);
    }
}

