public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        int Q = fs.nextInt();

        PriorityQueue<Long> left = new PriorityQueue<>(Collections.reverseOrder()); // max-heap
        PriorityQueue<Long> right = new PriorityQueue<>(); // min-heap

        long addLeft = 0;
        long addRight = 0;
        long minValue = 0;

        for (int qi = 0; qi < Q; qi++) {
            int t = fs.nextInt();
            if (t == 1) {
                long a = fs.nextLong();
                long b = fs.nextLong();

                minValue += b;

                if (left.isEmpty()) {
                    left.add(a - addLeft);
                    right.add(a - addRight);
                    continue;
                }

                long lmax = left.peek() + addLeft;
                long rmin = right.peek() + addRight;

                if (a < lmax) {
                    minValue += lmax - a;
                    left.poll();
                    left.add(a - addLeft);
                    left.add(a - addLeft);
                    right.add(lmax - addRight);
                } else if (a > rmin) {
                    minValue += a - rmin;
                    right.poll();
                    right.add(a - addRight);
                    right.add(a - addRight);
                    left.add(rmin - addLeft);
                } else {
                    left.add(a - addLeft);
                    right.add(a - addRight);
                }
            } else {
                long x = left.peek() + addLeft;
                out.append(x).append(' ').append(minValue).append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

