typedef struct {
    long long *data;
    int size;
    int capacity;
} Heap;

void swap(long long *a, long long *b) {
    long long t = *a;
    *a = *b;
    *b = t;
}

void push_max(Heap *h, long long val) {
    if (h->size == h->capacity) {
        h->capacity = h->capacity ? h->capacity * 2 : 4;
        h->data = realloc(h->data, h->capacity * sizeof(long long));
    }
    int i = h->size++;
    h->data[i] = val;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (h->data[p] >= h->data[i]) break;
        swap(&h->data[p], &h->data[i]);
        i = p;
    }
}

long long pop_max(Heap *h) {
    long long res = h->data[0];
    h->data[0] = h->data[--h->size];
    int i = 0;
    while (1) {
        int largest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        if (left < h->size && h->data[left] > h->data[largest]) largest = left;
        if (right < h->size && h->data[right] > h->data[largest]) largest = right;
        if (largest == i) break;
        swap(&h->data[i], &h->data[largest]);
        i = largest;
    }
    return res;
}

long long top_max(Heap *h) {
    return h->data[0];
}

void push_min(Heap *h, long long val) {
    if (h->size == h->capacity) {
        h->capacity = h->capacity ? h->capacity * 2 : 4;
        h->data = realloc(h->data, h->capacity * sizeof(long long));
    }
    int i = h->size++;
    h->data[i] = val;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (h->data[p] <= h->data[i]) break;
        swap(&h->data[p], &h->data[i]);
        i = p;
    }
}

long long pop_min(Heap *h) {
    long long res = h->data[0];
    h->data[0] = h->data[--h->size];
    int i = 0;
    while (1) {
        int smallest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        if (left < h->size && h->data[left] < h->data[smallest]) smallest = left;
        if (right < h->size && h->data[right] < h->data[smallest]) smallest = right;
        if (smallest == i) break;
        swap(&h->data[i], &h->data[smallest]);
        i = smallest;
    }
    return res;
}

long long top_min(Heap *h) {
    return h->data[0];
}

