typedef long long ll;

typedef struct {
    ll *a;
    int size;
    int cap;
    int is_min; /* 1: min-heap, 0: max-heap */
} Heap;

void heap_init(Heap *h, int cap, int is_min) {
    h->a = (ll*)malloc(sizeof(ll) * cap);
    h->size = 0;
    h->cap = cap;
    h->is_min = is_min;
}

void heap_free(Heap *h) {
    free(h->a);
}

int heap_cmp(Heap *h, ll x, ll y) {
    if (h->is_min) return x < y;
    return x > y;
}

void heap_push(Heap *h, ll v) {
    int i = h->size++;
    h->a[i] = v;
    while (i > 0) {
        int p = (i - 1) >> 1;
        if (heap_cmp(h, h->a[p], h->a[i])) break;
        ll tmp = h->a[p];
        h->a[p] = h->a[i];
        h->a[i] = tmp;
        i = p;
    }
}

ll heap_top(Heap *h) {
    return h->a[0];
}

ll heap_pop(Heap *h) {
    ll ret = h->a[0];
    h->size--;
    if (h->size > 0) {
        h->a[0] = h->a[h->size];
        int i = 0;
        while (1) {
            int l = i * 2 + 1;
            int r = i * 2 + 2;
            int best = i;
            if (l < h->size && !heap_cmp(h, h->a[best], h->a[l])) best = l;
            if (r < h->size && !heap_cmp(h, h->a[best], h->a[r])) best = r;
            if (best == i) break;
            ll tmp = h->a[i];
            h->a[i] = h->a[best];
            h->a[best] = tmp;
            i = best;
        }
    }
    return ret;
}

int main(void) {
    int Q;
    scanf("%d", &Q);

    Heap L, R;
    heap_init(&L, Q + 5, 0); /* max-heap */
    heap_init(&R, Q + 5, 1); /* min-heap */

    ll add = 0;

    for (int qi = 0; qi < Q; qi++) {
        int t;
        scanf("%d", &t);
        if (t == 1) {
            ll a, b;
            scanf("%lld %lld", &a, &b);
            add += b;

            if (L.size == 0) {
                heap_push(&L, a);
                heap_push(&R, a);
            } else {
                ll ltop = heap_top(&L);
                ll rtop = heap_top(&R);

                if (a < ltop) {
                    add += ltop - a;
                    heap_push(&L, a);
                    heap_push(&L, a);
                    heap_push(&R, heap_pop(&L));
                } else if (a > rtop) {
                    add += a - rtop;
                    heap_push(&R, a);
                    heap_push(&R, a);
                    heap_push(&L, heap_pop(&R));
                } else {
                    heap_push(&L, a);
                    heap_push(&R, a);
                }
            }
